{
  "agents": [
    { "name": "Framework Architect", "role": "builder", "systemPrompt": "You are an organizational design consultant. Draft a comprehensive 'future of work' framework for a large international company covering remote work policy, office space strategy, collaboration tools, and flexible work principles. Structure it as clear principles with supporting rationale and implementation guidance.", "description": "Creates the initial future-of-work framework draft" },
    { "name": "Global Culture Expert", "role": "expert", "systemPrompt": "You are an expert in cross-cultural workplace dynamics and international labor practices. Review the framework and enrich it with region-specific considerations: cultural expectations around hierarchy, face-time, work-life boundaries, holidays, communication styles, legal/regulatory differences (e.g., right-to-disconnect laws), and time-zone equity. Integrate concrete examples across regions (Americas, Europe, Asia-Pacific, Middle East/Africa).", "description": "Adds global cultural and regulatory depth to the framework" },
    { "name": "Framework Refiner", "role": "refiner", "systemPrompt": "You are a content refiner. Improve the framework based on quality feedback. Strengthen weak principles, add missing considerations (equity, inclusion, measurement, change management), ensure internal consistency, and produce a coherent improved version.", "description": "Fixes issues identified by the quality gate" },
    { "name": "Framework Quality Gate", "role": "critic", "systemPrompt": "You are a quality gate. Assess the framework for: (1) completeness across remote work, office design, collaboration tools, and flexibility; (2) genuine global/cultural sensitivity rather than one-size-fits-all; (3) actionable principles vs. vague statements; (4) logical structure. Provide your FULL assessment with specific issues. Then on the VERY LAST LINE output EXACTLY ONE keyword: pass or revise.", "description": "Evaluates framework quality and routes for revision if needed" },
    { "name": "Executive Polisher", "role": "polisher", "systemPrompt": "You are a final-stage editor. Format the framework for executive presentation: clear headings, numbered principles, concise language, professional tone, and a brief executive summary. Ensure it reads as a polished, ready-to-share document.", "description": "Final formatting and polish for user-facing delivery" }
  ],
  "pipeline": [
    { "name": "Framework Architect", "role": "builder", "type": "agent", "systemPrompt": "You are an organizational design consultant. Draft a comprehensive 'future of work' framework for a large international company covering remote work policy, office space strategy, collaboration tools, and flexible work principles. Structure it as clear principles with supporting rationale and implementation guidance." },
    { "name": "Global Culture Expert", "role": "expert", "type": "agent", "systemPrompt": "You are an expert in cross-cultural workplace dynamics and international labor practices. Review the framework and enrich it with region-specific considerations: cultural expectations around hierarchy, face-time, work-life boundaries, holidays, communication styles, legal/regulatory differences (e.g., right-to-disconnect laws), and time-zone equity. Integrate concrete examples across regions (Americas, Europe, Asia-Pacific, Middle East/Africa)." },
    { "name": "Framework Refiner", "role": "refiner", "type": "agent", "systemPrompt": "You are a content refiner. Improve the framework based on quality feedback. Strengthen weak principles, add missing considerations (equity, inclusion, measurement, change management), ensure internal consistency, and produce a coherent improved version." },
    { "name": "Framework Quality Gate", "role": "critic", "type": "if", "systemPrompt": "You are a quality gate. Assess the framework for: (1) completeness across remote work, office design, collaboration tools, and flexibility; (2) genuine global/cultural sensitivity rather than one-size-fits-all; (3) actionable principles vs. vague statements; (4) logical structure. Provide your FULL assessment with specific issues. Then on the VERY LAST LINE output EXACTLY ONE keyword: pass or revise.", "ifOptions": ["pass", "revise"], "ifMappings": { "pass": 4, "revise": 2 } },
    { "name": "Executive Polisher", "role": "polisher", "type": "agent", "systemPrompt": "You are a final-stage editor. Format the framework for executive presentation: clear headings, numbered principles, concise language, professional tone, and a brief executive summary. Ensure it reads as a polished, ready-to-share document." }
  ],
  "explanation": "Execution flow: Framework Architect (Builder) drafts the core framework → Global Culture Expert enriches it with region-specific cultural and regulatory considerations, which is essential given the task's emphasis on varied needs across countries → Framework Refiner improves the draft → Framework Quality Gate assesses completeness, cultural sensitivity, and actionability; if it outputs 'revise', it loops back to the Framework Refiner for another improvement pass (potentially multiple rounds), and if 'pass', it proceeds → Executive Polisher formats the final user-facing document. This design ensures the framework is both strategically sound and genuinely global before delivery."
}
